import { nativeGuard } from './native-guard.mjs';
export function setupExperience(app,show){
 const $=selector=>app.querySelector(selector);
 const native=!!window.Capacitor?.isNativePlatform();
 const guard=nativeGuard();
 const css=document.createElement('link');css.rel='stylesheet';css.href='mobile-setup.css';document.head.append(css);
 const login=document.createElement('button');login.className='m-account-entry';login.textContent='Sign in / Create account';
 $('[data-screen="home"]').prepend(login);
 login.onclick=()=>document.getElementById('authDialog')?.showModal();
 window.addEventListener('rebound:auth',event=>{login.textContent=event.detail.user?'My account':'Sign in / Create account';login.onclick=()=>event.detail.user?show('account'):document.getElementById('authDialog')?.showModal();});

 const setup=document.createElement('article');setup.className='guard-setup';
 setup.innerHTML='<h2>Set up Rebound</h2><p>Choose what Rebound can access. Android opens a separate settings page for each special permission.</p><p>Accessibility detects selected apps and short-video interface identifiers, counts scroll changes, and displays blocks. No messages or video content are stored or uploaded. You can turn it off in Android Settings.</p><div id="setup-permissions"></div><p role="status" id="setup-status"></p><button id="setup-settings">Open Rebound app settings</button>';
 $('[data-screen="profile"]').prepend(setup);
 const permissionItems=[['usage','Usage Access','Read today’s time in supported apps'],['accessibility','Accessibility','Detect reels and show time-limit interventions'],['overlay','Display over other apps','Show the floating usage counter'],['notifications','Notifications','Allow Rebound notifications']];
 const permissionButtons={};
 for(const [kind,title,description] of permissionItems){const row=document.createElement('div');row.className='setup-row';const label=document.createElement('div');const strong=document.createElement('strong');strong.textContent=title;const small=document.createElement('small');small.textContent=description;label.append(strong,small);const button=document.createElement('button');button.textContent='Connect';button.dataset.permission=kind;button.onclick=async()=>{if(!guard){$('#setup-status').textContent='This permission is available in the Android app.';return;}if(kind==='accessibility'&&!confirm('Enable Rebound Accessibility? Rebound detects selected apps and short-video interface IDs to estimate video changes and show blocks. It does not store messages or video content. You can revoke this access in Settings.'))return;try{await guard.permissions({kind});await refresh();}catch(e){$('#setup-status').textContent=e.message;}};row.append(label,button);$('#setup-permissions').append(row);permissionButtons[kind]=button;}
 $('#setup-settings').onclick=async()=>{if(!guard)return void($('#setup-status').textContent='Open app settings from the installed Android app.');try{await guard.openAppSettings();}catch(e){$('#setup-status').textContent=e.message;}};
 // Remove the old duplicated permission controls, whose status could be misleading.
 app.querySelectorAll('.m-permission').forEach(row=>row.hidden=true);
 // Use one configuration surface: legacy controls overwrite daily limits and advertise unsupported filters.
 $('#m-block-list').hidden=true;
 $('[data-screen="profile"]').querySelectorAll('.m-section-title').forEach(title=>title.hidden=true);
 const limitation=document.createElement('p');limitation.className='m-hint';limitation.textContent='Website filtering and YouTube channel allowlists are not available in this Android build.';setup.after(limitation);
 const apps=[['Instagram','com.instagram.android'],['YouTube','com.google.android.youtube'],['Facebook','com.facebook.katana'],['Snapchat','com.snapchat.android'],['X','com.twitter.android'],['TikTok','com.zhiliaoapp.musically'],['TikTok (alternate)','com.ss.android.ugc.trill']];
 const limits=document.createElement('article');limits.className='guard-setup';limits.innerHTML='<h2>App & short-video limits</h2><p>Choose a short-video allowance and an optional daily whole-app limit. The floating count is an estimate of detected video changes.</p><div id="managed-apps"></div><p role="status" id="limits-status"></p>';
 setup.after(limits);
 const saved=(()=>{try{return JSON.parse(localStorage.getItem('reboundLimits')||'{}');}catch{return {};}})();
 for(const [name,pkg] of apps){const row=document.createElement('div');row.className='limit-app';const title=document.createElement('h3');title.textContent=name;const reels=document.createElement('input');reels.type='number';reels.min='1';reels.max='180';reels.value=String(saved[pkg]?.minutes||20);const daily=document.createElement('input');daily.type='number';daily.min='0';daily.max='1440';daily.value=String(saved[pkg]?.dailyMinutes||0);const enabled=document.createElement('input');enabled.type='checkbox';enabled.checked=saved[pkg]?.enabled===true;
 const label=(text,input)=>{const l=document.createElement('label');l.append(document.createTextNode(text),input);return l;};
 const save=document.createElement('button');save.textContent='Save limit';save.onclick=async()=>{if(!reels.reportValidity()||!daily.reportValidity())return;const value={minutes:Number(reels.value),dailyMinutes:Number(daily.value),enabled:enabled.checked};try{if(guard)await guard.configure({package:pkg,...value});saved[pkg]=value;localStorage.setItem('reboundLimits',JSON.stringify(saved));$('#limits-status').textContent=guard?name+' limits saved.':name+' preview saved. Install the APK to monitor this app.';await refresh();}catch(e){$('#limits-status').textContent=e.message;}};
 const open=document.createElement('button');open.textContent='Open '+name;open.onclick=async()=>{if(!guard)return void($('#limits-status').textContent='Opening installed apps is available on Android.');try{await guard.launchApp({package:pkg});}catch(e){$('#limits-status').textContent=e.message;}};
 const usage=document.createElement('small');usage.dataset.usagePackage=pkg;usage.textContent='No device data';row.append(title,label('Monitor short videos',enabled),label('Session / extension minutes',reels),label('Daily app limit (0 = off)',daily),save,open,usage);$('#managed-apps').append(row);}
 async function refresh(){if(!guard)return;try{const state=await guard.status();for(const [kind] of permissionItems)permissionButtons[kind].textContent=state[kind]?'Enabled':'Connect';$('#setup-status').textContent=state.accessibility&&state.usage?'Monitoring permissions ready. Select and save app limits below.':'Complete Usage Access and Accessibility to start monitoring.';for(const usage of state.apps||[]){const node=app.querySelector(`[data-usage-package="${usage.package}"]`);if(node)node.textContent=`Today: ${Math.floor(usage.usageMs/60000)} min in app · ${Math.floor(usage.scrollMs/60000)} min in short videos · ~${usage.videos} videos`;}}catch(e){$('#setup-status').textContent=e.message;}}
 window.addEventListener('focus',refresh);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});refresh();
 if(native&&!localStorage.getItem('reboundSetupV2')){show('profile');localStorage.setItem('reboundSetupV2','shown');}
 // Native focus timestamps also power the floating counter outside the WebView.
 let focusStarted=0,focusAccumulated=0;
 $('#m-start-timer').addEventListener('click',async()=>{const running=$('#m-start-timer').textContent.includes('Pause');if(running)focusStarted=Date.now();else if(focusStarted){focusAccumulated+=Date.now()-focusStarted;focusStarted=0;}if(guard)try{const [m,s]=$('#m-clock').textContent.split(':').map(Number);await guard.focusState({running,remainingSeconds:m*60+s,elapsedMs:focusAccumulated});}catch(e){$('#setup-status').textContent=e.message;}});

 const locationDialog=document.createElement('dialog');locationDialog.className='location-dialog';locationDialog.innerHTML='<form method="dialog"><button aria-label="Close location">Close</button></form><h2>Your study location</h2><div class="location-scene"><div data-location-avatar></div><span>You are here</span></div><p id="location-coordinates"></p><p id="location-accuracy"></p><a id="location-map" target="_blank" rel="noopener">Open map</a><button id="location-send">Share this location</button><p role="status" id="location-result">Visible only to you until you choose Share.</p>';
 app.append(locationDialog);let currentLocation=null;
 $('#m-share-location').textContent='View my location';
 $('#m-share-location').onclick=async()=>{const output=$('#m-location-status');output.textContent='Requesting your location…';try{const coords=guard?await guard.location():await new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(new Error('Location is unavailable.'));navigator.geolocation.getCurrentPosition(p=>resolve(p.coords),reject,{timeout:15000,maximumAge:0});});currentLocation=coords;$('#location-coordinates').textContent=`${coords.latitude.toFixed(5)}, ${coords.longitude.toFixed(5)}`;$('#location-accuracy').textContent=`Accuracy: approximately ${Math.round(coords.accuracy)} metres`;$('#location-map').href=`https://maps.google.com/?q=${coords.latitude},${coords.longitude}`;const avatar=$('.wardrobe-mini svg');if(avatar)$('[data-location-avatar]').replaceChildren(avatar.cloneNode(true));$('#location-result').textContent='Visible only to you until you choose Share.';locationDialog.showModal();output.textContent='Location shown with your avatar. Not uploaded to your account.';}catch(e){output.textContent=e.message||'Location denied or unavailable. You can try again.';}};
 $('#location-send').onclick=async()=>{if(!currentLocation)return;const text=`My Rebound study location: https://maps.google.com/?q=${currentLocation.latitude},${currentLocation.longitude}`;try{if(guard)await guard.share({text});else if(navigator.share)await navigator.share({title:'My Rebound location',text});else{await navigator.clipboard.writeText(text);$('#location-result').textContent='Map link copied. Paste it only where you want to share.';return;}$('#location-result').textContent='Share sheet opened. Choose who receives your location.';}catch{$('#location-result').textContent='Location was not shared.';}};
}
